// test/hashing.test.js
const PasswordHasher = require('../auth/hashService');

describe('PasswordHasher', () => {
  test('should produce valid Argon2id hash with correct format', async () => {
    const password = 'SecurePass123!';
    const result = await PasswordHasher.hash(password);

    expect(result.hash).toMatch(/^\$argon2id\$v=19\$/);
    expect(result.hash).toMatch(/\$[A-Za-z0-9+/]+={0,2}\$[A-Za-z0-9+/]+={0,2}$/);

    // Verify it can be verified
    const isValid = await PasswordHasher.verify(password, result.hash);
    expect(isValid).toBe(true);
  });
});
```

